<script setup lang="ts">
import { newStoreId } from '~/shared/cms/store-location.mjs'
const props=defineProps<{modelValue:any;schema:any;label?:string;path?:string}>()
const emit=defineEmits<{ 'update:modelValue':[value:any] }>()
const search=ref(''),page=ref(1),picker=ref(false)
const title=computed(()=>props.schema.label||'內容項目')
const hintId=useId()
const fields=computed(()=>Object.entries(props.schema.fields||{}).filter(([,s]:any)=>!Object.hasOwn(s,'fixed')&&!s.hidden) as [string,any][])
const rows=computed(()=>Array.isArray(props.modelValue)?props.modelValue.map((value:any,index:number)=>({value,index})).filter((r:any)=>JSON.stringify(r.value).toLowerCase().includes(search.value.toLowerCase())):[])
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/10)))
watch(search,()=>page.value=1)
function set(key:string,value:any){emit('update:modelValue',{...props.modelValue,[key]:value})}
function item(index:number,value:any){const a=[...(props.modelValue||[])];a[index]=value;emit('update:modelValue',a)}
function move(index:number,step:number){const a=[...(props.modelValue||[])];if(index+step<0||index+step>=a.length)return;[a[index],a[index+step]]=[a[index+step],a[index]];if(props.schema.source)a.forEach((v:any,i:number)=>v.sort=i);emit('update:modelValue',a)}
function add(){const t=JSON.parse(JSON.stringify(props.schema.template??''));if(t&&typeof t==='object'&&!Array.isArray(t)){if('id'in t)t.id=props.schema.idGenerator==='store'?newStoreId(props.modelValue||[]):typeof t.id==='number'?Math.max(0,...(props.modelValue||[]).map((v:any)=>Number(v.id)||0))+1:crypto.randomUUID();if('slug'in t)t.slug='new-'+crypto.randomUUID().slice(0,8);if(t.summary)t.summary.title='新增內容';if('title'in t)t.title='新增內容';if('name'in t)t.name=props.schema.newItemLabel||'新增項目'}emit('update:modelValue',[...(props.modelValue||[]),t]);search.value='';page.value=Math.ceil(((props.modelValue?.length||0)+1)/10)}
function remove(index:number){emit('update:modelValue',props.modelValue.filter((_:any,i:number)=>i!==index));page.value=Math.min(page.value,Math.max(1,Math.ceil((props.modelValue.length-1)/10)))}
function caption(value:any,index:number){return typeof value==='object'&&value?((props.schema.rowLabel&&value[props.schema.rowLabel])||value.summary?.title||value.title||value.name||value.zh||value.en||value.question||value.label||value.heading||value.model||`項目 ${index+1}`):`${props.schema.item?.format==='media'?'圖片':'文字項目'} ${index+1}`}
function thumbnail(value:any){const image=value?.[props.schema.rowImage];return Array.isArray(image)?image[0]:image}
</script>
<template>
 <AdminStoreRegions v-if="schema.editor==='store-regions'" :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" />
 <fieldset v-else-if="schema.type==='object'" class="cms-fields"><legend v-if="label">{{ title }}</legend><AdminHeroImages v-if="schema.editor==='hero-images'" :model-value="modelValue" :style="{ '--hero-pan-x': Number(path?.split('.').at(-1)) % 2 === 1 ? '4%' : '-4%' }" @update:model-value="emit('update:modelValue',$event)" /><AdminStoreLocation v-if="schema.editor==='store-location'" :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" /><AdminFields v-for="[key,field] in fields" :key="key" :model-value="modelValue?.[key]" :schema="field" :label="key" :path="`${path||''}.${key}`" @update:model-value="set(key,$event)" /></fieldset>
 <AdminHomeCases v-else-if="schema.editor==='home-cases'" :model-value="modelValue" :label="title" @update:model-value="emit('update:modelValue',$event)" />
 <section v-else-if="schema.type==='array'" class="cms-array"><div class="cms-section-heading"><strong>{{ title }} <span class="cms-count">{{ modelValue?.length||0 }}</span></strong><button v-if="!schema.source" type="button" class="cms-button" @click="add">新增項目</button></div><p v-if="schema.help" class="cms-field-help cms-array-help">{{ schema.help }}</p><label v-if="(modelValue?.length||0)>10" class="cms-search"><input v-model="search" :aria-label="`搜尋${title}`" placeholder="搜尋項目" /></label><details v-for="row in rows.slice((page-1)*10,page*10)" :key="row.value?.id??row.index" class="cms-array-row"><summary><span v-if="schema.rowImage" class="cms-array-summary-content"><AdminImage v-if="thumbnail(row.value)" :src="thumbnail(row.value)" :alt="`${caption(row.value,row.index)}預覽縮圖`" class="cms-array-thumbnail" /><span v-else class="cms-array-thumbnail cms-array-thumbnail-empty" aria-hidden="true">未設定圖片</span><span>{{ caption(row.value,row.index) }}</span></span><template v-else>{{ caption(row.value,row.index) }}</template></summary><div class="cms-actions"><button type="button" class="cms-button" :disabled="row.index===0" @click="move(row.index,-1)">上移</button><button type="button" class="cms-button" :disabled="row.index===modelValue.length-1" @click="move(row.index,1)">下移</button><button type="button" class="cms-button" :disabled="schema.source||modelValue.length<=(schema.min||0)" @click="remove(row.index)">移除此項</button></div><AdminFields :model-value="row.value" :schema="schema.itemLabels?{...schema.item,label:schema.itemLabels[row.index]}:schema.item" :path="`${path||''}.${row.index}`" @update:model-value="item(row.index,$event)" /></details><div v-if="pages>1" class="cms-actions"><button type="button" class="cms-button" :disabled="page===1" @click="page--">上一頁</button><span>{{ page }} / {{ pages }}</span><button type="button" class="cms-button" :disabled="page>=pages" @click="page++">下一頁</button></div></section>
 <div v-else-if="schema.enum" class="cms-field"><label :for="hintId+'-select'">{{ title }}</label><select :id="hintId+'-select'" :value="modelValue" :aria-describedby="schema.help?hintId:undefined" @change="emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option v-if="schema.optionLabels&&!schema.enum.includes(modelValue)" :value="modelValue">目前自訂尺寸（保留）</option><option v-for="(v,index) in schema.enum" :key="v" :value="v">{{ schema.optionLabels?.[index]||({latest:'最新消息',activities:'優惠活動',video:'影音'} as any)[v]||v }}</option></select><p v-if="schema.help" :id="hintId" class="cms-field-help">{{ schema.help }}</p></div>
 <div v-else-if="schema.type==='boolean'" class="cms-field"><label class="cms-checkbox"><input type="checkbox" :checked="modelValue" :aria-describedby="schema.help?hintId:undefined" @change="emit('update:modelValue',($event.target as HTMLInputElement).checked)" />{{ title }}</label><p v-if="schema.help" :id="hintId" class="cms-field-help">{{ schema.help }}</p></div>
 <label v-else-if="schema.type==='number'" class="cms-field">{{ title }}<input type="number" :value="modelValue" @input="emit('update:modelValue',Number(($event.target as HTMLInputElement).value))" /></label>
 <div v-else class="cms-field"><label>{{ title }}<textarea :aria-describedby="schema.help?hintId:undefined" :readonly="schema.readOnly" v-if="!schema.format&&!schema.identity" :value="modelValue??''" rows="2" @input="emit('update:modelValue',($event.target as HTMLTextAreaElement).value)" /><input v-else :aria-describedby="schema.help?hintId:undefined" :readonly="schema.readOnly" :value="modelValue??''" @input="emit('update:modelValue',($event.target as HTMLInputElement).value)" /></label><p v-if="schema.help" :id="hintId" class="cms-field-help">{{ schema.help }}</p><template v-if="schema.format==='media'||label==='pdfUrl'"><AdminImage v-if="modelValue&&!String(modelValue).endsWith('.pdf')" :src="modelValue" :alt="title" class="cms-field-thumbnail" :class="{'cms-field-thumbnail-dark':schema.previewTone==='dark'}" /><button type="button" class="cms-button" @click="($event.currentTarget as HTMLButtonElement).focus();picker=true">從媒體庫選擇</button><AdminDialog :open="picker" title="選擇素材" wide @close="picker=false"><AdminMediaGrid picking :kind="label==='pdfUrl'||label==='brochureUrl'?'pdf':'image'" @select="emit('update:modelValue',$event.src);picker=false" /></AdminDialog></template></div>
</template>
